let nFrames = 32;
let phasor = 0.0;
let phasorInc = 1.0 / float(nFrames);
let circles;
let coal;

function setup() {
  createCanvas(1024, 768);

  circles = new ArrayList();
  let nCircles = 256.0;

  for (i = 0; i < int(nCircles); i++) {
    let n = float(i) / nCircles;
    let d = n * 256 + 1;
    let randomAngle = 0.25 * (1 - n);

    circles.add(new CirclesOnALine(new PVector(0.618 * width, n * height * 0.618 + height * (1 - 0.618)),
                n * 6 + 0.5,
                d,
                i % 2 * PI * random(-randomAngle, randomAngle)));
  }
}

function draw() {
  background(0);
	colorMode(HSB, 360, 255, 255);
  noStroke();
  fill(255);

  let lsSize = circles.size();

  for (i = 0; i < lsSize; i++) {
		fill(random(360), 255, 255);
    let thisCircle = (CirclesOnALine) circles.get(i);
    thisCircle.draw();
  }

  updatePhasor();

