function getVCoordinates(v, d, a) {
  return new PVector(v.x + d * cos(a), v.y + d * sin(a)); 
}

function updatePhasor() {
  phasor += phasorInc;

  if (phasor >= 1.0) {
    phasor -= 1.0;
  }
}

class CirclesOnALine {
  v;
  r, d, a;  // radius, distance, angle

  constructor(v_, r_, d_, a_) {
    v = v_;
    r = r_;
    d = d_;
    a = a_;
  }

  function draw() {
    let v1 = getVCoordinates(v, d * phasor, a + PI);

    while (v1.x > -r && v1.x < width + r
           && v1.y > -r && v1.y < height + r) {
      v1 = getVCoordinates(v1, d, a + PI);
    }

    do {
      fill(random(360), 255, 255);
      ellipse(v1.x, v1.y, r, r);
      v1 = getVCoordinates(v1, d, a);
    } while (v1.x > -r && v1.x < width + r
             && v1.y > -r && v1.y < height + r);
  }
}

function inBounds(x, y) {
  return (x > 0 && x <= width && y > 0 && y < height);
}

